"""New cause/terminal candidate: two native compiles, unchanged legacy evidence."""
from __future__ import annotations
import gc, hashlib, importlib, json, os, shutil, sys, time, traceback, weakref
from pathlib import Path
from unittest.mock import patch
ROOT=Path("/home/qq/hia-native-self-rewrite-20261111-dda7/normalization-v70-r1")
ORIGINAL_SOURCE=ROOT/"source"
SOURCE=ROOT/"source-cause-terminal-r4"
OLD=ROOT/"evidence"/"source-reconstruction-native-baseline-r1"
READBACK=ROOT/"evidence"/"baseline-observation-recovery-r2"
CASE=ROOT/"evidence"/"cause-terminal-r4"
COMPILER=Path("/home/qq/hia-native-self-rewrite-20261111-dda7/qualification-published-v68-e03c82d1-r1/qualification/cold.cold/qualification.evidence/B3.image.bin")
COMPILER_SHA="81b6fad94493546b5bf3f858248f25b19aded88bf8f3aaad18140aa317dac109"
PACKAGE=ROOT/"helpers"/"cause_terminal_r4_input.json"
CASE.mkdir(mode=0o700,exist_ok=False)
started=time.monotonic_ns()
def digest(raw):return hashlib.sha256(raw).hexdigest()
def encoded(value):return (json.dumps(value,sort_keys=True,indent=2,ensure_ascii=True)+"\n").encode("ascii")
def put(path,raw):
    path.parent.mkdir(parents=True,exist_ok=True)
    with path.open("xb") as f:f.write(raw);f.flush();os.fsync(f.fileno())
def check(root,expected):
    result={}
    for name,row in sorted(expected.items()):
        p=root/name
        assert p.is_file() and not p.is_symlink(),("source type",str(p))
        raw=p.read_bytes()
        actual={"bytes":len(raw),"sha256":digest(raw)}
        assert actual==row,("source identity",str(p),row,actual)
        result[name]=actual
    return result
def safe_value(value):
    if value is None or type(value) in (str,int,bool,float): return value
    if type(value) is bytes:
        return {"representation":"exact-bytes","hex":value.hex(),"bytes":len(value),"sha256":digest(value)}
    if type(value) in (tuple,list): return [safe_value(item) for item in value]
    return {"representation":"opaque-not-inspected","type":type(value).__name__}
def error_state(error):
    if error is None: return None
    result={"type":type(error).__module__+"."+type(error).__qualname__,
            "args":safe_value(error.args),"code":getattr(error,"code",None),
            "notes":safe_value(getattr(error,"__notes__",None)),
            "cause":error_state(error.__cause__)}
    for name in ("encoding","start","end","reason","pos","lineno","colno"):
        if hasattr(error,name): result[name]=safe_value(getattr(error,name))
    for name in ("doc","object"):
        if hasattr(error,name):
            value=getattr(error,name)
            raw=value.encode("utf-8","surrogatepass") if type(value) is str else value
            result[name]={"type":type(value).__name__,"length":len(value),"sha256":digest(raw)}
    return result
def outcome(function,value):
    try: result=function(value)
    except BaseException as error: return {"error":error_state(error)}
    result,wire=result
    return {"error":None,"value":result,"wire_hex":wire.hex(),"wire_sha256":digest(wire)}

def late(value,trace,root_destructor=False):
    class Meta(type):
        calls=0
        def __eq__(cls,other):cls.calls+=1;return cls.calls>2 and other is list
    class Foreign(dict,metaclass=Meta):
        def __len__(self):return 0
        def __iter__(self):return iter(())
        def __del__(self):
            if root_destructor:trace.append('root_del')
    return Foreign(node=value)

def fixture(name,trace):
    if name in ('poison_key','temporary_key','wide_type_key'):
        class NameMeta(type):
            def __getattribute__(cls,name):
                if name in ('__name__','__qualname__','__module__'):
                    trace.append('forbidden_type_attribute:'+name);raise RuntimeError('unexpected type attribute')
                return type.__getattribute__(cls,name)
        class Key(metaclass=NameMeta):
            def __hash__(self):trace.append('forbidden_hash');raise RuntimeError('unexpected key hash')
            def __repr__(self):trace.append('forbidden_repr');raise RuntimeError('unexpected key repr')
            @property
            def __class__(self):trace.append('forbidden_class');raise RuntimeError('unexpected class')
            def __del__(self):trace.append('key_del')
        if name=='wide_type_key':
            Key=NameMeta('甲'*110,(),{'__hash__':Key.__hash__,'__del__':Key.__del__})
        class Mapping(dict):
            def items(self):trace.append('items');return [(Key(),1)]
        return late(Mapping(physical=0),trace)
    if name=='list_cycle':
        class Ring(list):
            def __iter__(self):trace.append('ring_iter');return iter([self])
        return late(Ring([0]),trace)
    if name=='dict_cycle':
        class Ring(dict):
            def items(self):trace.append('ring_items');return [('again',self)]
        return late(Ring(physical=0),trace)
    if name=='error_releases_ephemeral_root':return late(object(),trace,True)
    raise AssertionError(name)


def observe_foreign(call,name):
    trace=[]
    try:
        call(fixture(name,trace))
        result={"status":"returned"}
    except BaseException as error:
        cause=error.__cause__
        result={"status":"raised","type":type(error).__name__,"message":str(error),
                "code":getattr(error,"code",None),
                "cause":None if cause is None else {"type":type(cause).__name__,
                    "message":str(cause),"notes":getattr(cause,"__notes__",[])}}
        cause=None
    trace.append("caller_exception_released")
    return {"outcome":result,"trace_at_return":list(trace)}


def held_error_lifetime(call):
    trace=[];refs=[]
    def make():
        value=fixture("error_releases_ephemeral_root",trace)
        refs.append(weakref.ref(value))
        return value
    held=None
    try:call(make())
    except BaseException as error:held=error
    assert held is not None
    during={"root_alive":refs[0]() is not None,"trace":list(trace)}
    held=None
    after={"root_alive":refs[0]() is not None,"trace":list(trace)}
    return {"while_original_error_held":during,"after_error_released":after}
report={"schema":"hia.normalization.v70.cause-terminal-development.v1",
 "scope":"Two changed HIA components rebuilt; three immutable components reused with original receipts. Full owner, Python3.14 ancestor notes and physical recursion remain incomplete.",
 "full_owner_qualified":False,"current_source_cold_qualified":False,
 "physical_recursion_qualified":False,"notes_coordinator_qualified":False,
 "old_541a_identity_claimed":False,"python":sys.version,
 "observations":[],"differences":[],"failures":[],"new_compile_count":0}
before=None;original_before=None;native_original_before=None;compiler_bytes=None;journal=None
try:
    package_raw=PACKAGE.read_bytes()
    assert digest(package_raw)=="949a5b511d40fa32c12d18b937173788a8b0eed9f0e0b9d6b6fadaea1eec3173"
    package=json.loads(package_raw)
    put(CASE/"INPUT.json",package_raw)
    report["input_sha256"]=digest(package_raw)
    old_report_raw=(READBACK/"RESULT.json").read_bytes()
    assert digest(old_report_raw)=="d45f4c214ae3ea02edfa95659f4d4658f7958a8b6cb9ade04b2d5e75ca7ee01b"
    old_report=json.loads(old_report_raw)
    original_identity_raw=(READBACK/"SOURCE_IDENTITY.json").read_bytes()
    assert digest(original_identity_raw)==old_report["source_identity"]["sha256"]
    original_identity=json.loads(original_identity_raw)
    original_before=check(ORIGINAL_SOURCE,original_identity)
    native_original_before=check(OLD/"native",old_report["native_artifact_identity"])
    assert not SOURCE.exists()
    shutil.copytree(ORIGINAL_SOURCE,SOURCE,symlinks=True,
        ignore=shutil.ignore_patterns(".git","__pycache__","*.pyc",".pytest_cache"))
    check(SOURCE,original_identity)
    expected=dict(original_identity)
    for name,text in package["files"].items():
        raw=text.encode("utf-8")
        assert package["metadata"][name]=={"bytes":len(raw),"sha256":digest(raw)}
        target=SOURCE/name
        target.parent.mkdir(parents=True,exist_ok=True)
        target.write_bytes(raw)
        expected[name]=package["metadata"][name]
    for key in list(os.environ):
        if key.startswith("HEPTA_HIA_"):del os.environ[key]
    sys.dont_write_bytecode=True;os.chdir(SOURCE);sys.path.insert(0,str(SOURCE))
    from hepta.hia_agent_assembly import render_assembly,assemble_program
    report["regeneration"]={}
    for module,name in [
        ("tools.generate_hia_program_normalization","examples/hia_bootstrap/program_normalization.hiaasm"),
        ("tools.generate_hia_core_json_bytes","examples/hia_bootstrap/core_json_bytes.hepta")]:
        target=SOURCE/name;target.unlink()
        assert not target.exists()
        document=importlib.import_module(module).document()
        generated=render_assembly(document).encode("utf-8")
        assert not target.exists()
        put(target,generated);put(CASE/Path(name).name,generated)
        assert render_assembly(importlib.import_module(module).document()).encode("utf-8")==generated
        expected[name]={"bytes":len(generated),"sha256":digest(generated)}
        report["regeneration"][name]={**expected[name],
            "final_output_absent_during_first_render":True,
            "functions":len(document["functions"]),
            "max_function_blocks":max(len(f["blocks"]) for f in document["functions"]),
            "max_block_parameters":max(len(b["params"]) for f in document["functions"] for b in f["blocks"])}
    before=check(SOURCE,expected)
    put(CASE/"SOURCE_IDENTITY.json",encoded(before))
    compiler_bytes=COMPILER.read_bytes()
    assert len(compiler_bytes)==669494 and digest(compiler_bytes)==COMPILER_SHA
    native=CASE/"native";native.mkdir(mode=0o700)
    held_compiler=native/"retained-e03-B3.image.bin";put(held_compiler,compiler_bytes)
    from tools.qualify_hia_selfhost import compile_stage
    from tools.build_hia_core_json_bytes import admit_compile_receipt
    from hepta.hia_program_normalization_native import SOURCES,SCHEMA,installed_program_normalization
    manifest={"schema":SCHEMA,"images":{}}
    report["components"]={}
    for name,path in SOURCES.items():
        source=path.read_bytes()
        if name in ("normalization","front"):
            image,receipt=compile_stage(native,name,held_compiler,source)
            report["new_compile_count"]+=1
            image_bytes=image.read_bytes()
            origin="new development compile"
        else:
            prior=old_report["retained_native_compile_receipts"][name]
            assert prior["source_sha256"]==digest(source)
            prior_image=Path(prior["image_path"])
            image_bytes=prior_image.read_bytes()
            assert digest(image_bytes)==prior["image_sha256"]
            image=native/(name+".image.bin");put(image,image_bytes)
            receipt=prior["receipt"]
            origin=str(prior_image)
            put(native/(name+".original-compile-receipt.json"),encoded(receipt))
        admit_compile_receipt(receipt,compiler_bytes=compiler_bytes,source_bytes=source,image_bytes=image_bytes)
        assert held_compiler.read_bytes()==compiler_bytes and path.read_bytes()==source
        manifest["images"][name]={"image_path":image.name,"source_sha256":digest(source),"image_sha256":digest(image_bytes)}
        report["components"][name]={**manifest["images"][name],"image_bytes":len(image_bytes),
            "source_bytes":len(source),"origin":origin,"receipt":receipt}
    manifest_path=native/"manifest.json";put(manifest_path,encoded(manifest))
    owner=installed_program_normalization(manifest_path)
    from hepta.hia_program import _decode
    assert digest((SOURCE/"hepta/hia_program.py").read_bytes())=="76a222745e13fe29825a661be206243f137ada7b57292b07ab7513a40146fb92"
    journal=(CASE/"observations.jsonl").open("xb")
    def record(row):
        report["observations"].append(row)
        if not row["equal"]:report["differences"].append(row["case"])
        journal.write((json.dumps(row,sort_keys=True,ensure_ascii=True)+"\n").encode("ascii"))
        journal.flush();os.fsync(journal.fileno())
    cases=[
        ("raw_canonical",lambda:b' {"z":[true,null,-0],"a":"\\u00e9"} '),
        ("text_canonical",lambda:' {"z":2,"a":"é"} '),
        ("caller_snapshot",lambda:{"z":[True,None,17],"a":"é"}),
        ("null",lambda:None),("huge_integer_boundary_small",lambda:-(1<<1024)),
        ("raw_invalid_UTF8",lambda:b'["ok"]\xff'),
        ("raw_duplicate_key",lambda:b'{"a":0,"a":1}'),
        ("raw_invalid_grammar",lambda:b'{"a": }'),
        ("raw_unpaired_surrogate",lambda:b'"\\ud800"')]

    for name,make in cases:
        reference=outcome(_decode,make())
        with patch("json.dumps",side_effect=AssertionError("whole-payload hosted serializer entered")),\
             patch("json.loads",side_effect=AssertionError("whole-payload hosted parser entered")):
            actual=outcome(owner.normalize_program,make())
        record({"group":"baseline","case":name,"original":reference,"native":actual,"equal":reference==actual})
    enabled=gc.isenabled();gc.disable()
    try:
        for name in ("poison_key","temporary_key","wide_type_key","list_cycle","dict_cycle","error_releases_ephemeral_root"):
            reference=observe_foreign(_decode,name)
            with patch("json.dumps",side_effect=AssertionError("whole-payload hosted serializer entered")),\
                 patch("json.loads",side_effect=AssertionError("whole-payload hosted parser entered")):
                actual=observe_foreign(owner.normalize_program,name)
            record({"group":"foreign_error_and_lifetime","case":name,"original":reference,"native":actual,"equal":reference==actual})
            gc.collect()
        original=held_error_lifetime(_decode)
        actual=held_error_lifetime(owner.normalize_program)
        record({"group":"terminal_custody","case":"root_lives_with_delivered_error_then_dies_without_GC",
            "original":original,"native":actual,"equal":original==actual})
    finally:
        if enabled:gc.enable()
    # All full differences remain visible, including the six expected missing
    # CPython3.14 parent notes. These narrower assertions qualify only changed
    # causes and terminal custody, never the complete normalization owner.
    baseline=[x for x in report["observations"] if x["group"]=="baseline"]
    assert len(baseline)==9 and all(x["equal"] for x in baseline),"changed original wire causes differ"
    for row in report["observations"]:
        if row["group"]!="foreign_error_and_lifetime":continue
        assert row["original"]["trace_at_return"]==row["native"]["trace_at_return"],("foreign trace differs",row["case"])
        left=dict(row["original"]["outcome"]);right=dict(row["native"]["outcome"])
        for part in (left,right):
            if part.get("cause") is not None:
                part["cause"]=dict(part["cause"]);part["cause"].pop("notes",None)
        assert left==right,("fixed original cause differs",row["case"])
    assert report["observations"][-1]["equal"],"delivered exception has different root custody"
    report["status"]="PASS_CHANGED_CAUSES_AND_TERMINAL_CUSTODY_ONLY"
except BaseException:
    report["status"]="FAILED_CANDIDATE_OR_HARNESS"
    report["failures"].append(traceback.format_exc())
finally:
    if journal is not None:journal.close()
    try:
        if before is not None:
            after=check(SOURCE,before);assert after==before
            report["source_before_after_unchanged"]=True
            identity_raw=(CASE/"SOURCE_IDENTITY.json").read_bytes()
            report["source_identity"]={"path":str(CASE/"SOURCE_IDENTITY.json"),
                "files":len(before),"bytes":len(identity_raw),"sha256":digest(identity_raw)}
        if original_before is not None:
            assert check(ORIGINAL_SOURCE,original_before)==original_before
            report["original_source_unchanged"]=True
        if native_original_before is not None:
            assert check(OLD/"native",native_original_before)==native_original_before
            report["original_native_artifacts_unchanged"]=True
        if compiler_bytes is not None:
            assert COMPILER.read_bytes()==compiler_bytes
            report["original_compiler_unchanged"]=True
    except BaseException:
        report["status"]="FAILED_CANDIDATE_OR_HARNESS"
        report["failures"].append(traceback.format_exc())
    report["elapsed_ns"]=time.monotonic_ns()-started
    report["script_sha256"]=digest(Path(__file__).read_bytes())
    raw=encoded(report);put(CASE/"RESULT.json",raw)
    print(json.dumps({"status":report["status"],"result":str(CASE/"RESULT.json"),"bytes":len(raw),
        "sha256":digest(raw),"new_compile_count":report["new_compile_count"],
        "observations":len(report["observations"]),"full_matches":sum(r["equal"] for r in report["observations"]),
        "remaining_differences":report["differences"],"full_owner_qualified":False},sort_keys=True))
if report["status"]!="PASS_CHANGED_CAUSES_AND_TERMINAL_CUSTODY_ONLY":raise SystemExit(1)

