def late_error_lifetime(call,kind):
    trace=[]
    class Number(int):
        def __repr__(self):raise AssertionError("foreign int repr override")
        def __del__(self):trace.append("integer_del")
    class BadItem:
        def __del__(self):trace.append("item_del")
    class Mapping(dict):
        def items(self):
            trace.append("items")
            return [("key",Number(10**699))] if kind=="integer" else [BadItem()]
    root=baseline["late"](Mapping(physical=0),trace,True)
    root_ref=weakref.ref(root)
    held=None
    try:call(root)
    except BaseException as error:
        held=error
        result={"exception":note_state(error)}
    else:raise AssertionError("late error lifetime fixture did not fail")
    root=None
    result["while_held"]={"root_alive":root_ref() is not None,"trace":list(trace)}
    held=None
    result["after_release"]={"root_alive":root_ref() is not None,"trace":list(trace)}
    return result

def late_diagnostic_ack_fault(owner,kind,after):
    from hepta.hia_program_normalization_native import NormalizationContext,NormalizationProtocolError
    trace=[]
    class Mapping(dict):
        def items(self):
            trace.append("items")
            return [("key",10**699)] if kind=="integer" else [None]
    context=NormalizationContext(owner,baseline["late"](Mapping(physical=0),trace))
    frame=context._issued
    calls=[]
    old_foreign=NormalizationContext._foreign
    old_entry=NormalizationContext._enter
    def counted(self,current):
        if self is context and current[2]==62:calls.append(current[5])
        return old_foreign(self,current)
    injected=KeyboardInterrupt("lost late diagnostic ACK")
    injected_seen=False
    def interrupted(self,event,current,reply):
        nonlocal injected_seen
        if self is context and event==2 and current is frame:
            if after:old_entry(self,event,current,reply)
            injected_seen=True
            raise injected
        return old_entry(self,event,current,reply)
    with patch.object(NormalizationContext,"_foreign",counted):
        while frame[2] and frame[2]!=62:
            frame=context.accept(frame,context.observe(frame))
        expected_kind=3 if kind=="integer" else 4
        assert frame[2]==62 and frame[5]==expected_kind,frame
        reply=context.observe(frame)
        assert reply[0]==3 and calls==[expected_kind]
        with patch.object(NormalizationContext,"_enter",interrupted):
            try:context.accept(frame,reply)
            except KeyboardInterrupt as error:assert error is injected
            else:raise AssertionError("diagnostic interruption not observed")
        assert injected_seen and context.closed and context._failed
        assert context.output is None and context.workspace is None
        for operation in (lambda:context.observe(frame),lambda:context.accept(frame,reply)):
            try:operation()
            except NormalizationProtocolError:pass
            else:raise AssertionError("consumed diagnostic replayed")
        assert calls==[expected_kind]
    return {"kind":kind,"after_native_ack":after,"diagnostic_calls":calls,
        "injected":True,"closed":True,"arenas_closed":True,"replay_refused":2}

