import hashlib, importlib.util, json, os
from pathlib import Path
import sys, time, traceback

ROOT = Path("/home/qq/hia-native-self-rewrite-20261111-dda7/normalization-v70-r1")
CASE = ROOT / "evidence" / "cpython314-note-context-r2"
IMAGE = ROOT / "evidence" / "cpython314-note-primitive-r1" / "_hia_normalization_note_314.cpython-314-x86_64-linux-gnu.so"
SOURCE = ROOT / "helpers" / "cpython314_note_transport.c"
IMAGE_SHA = "613c879cb71539d2d49291f7ed088c41504243684b78ae48c974d308db1c33a8"
SOURCE_SHA = "edbceed8465afcd5a7533259580f044f28563835920a1af66f1a464e52a0c861"

def state(error):
    visited = set()
    def visit(error):
        if error is None: return None
        if id(error) in visited: return {"cycle": True, "type": type(error).__name__}
        visited.add(id(error))
        return {"type": type(error).__module__ + "." + type(error).__qualname__,
                "args": list(error.args), "notes": getattr(error, "__notes__", None),
                "context": visit(error.__context__), "cause": visit(error.__cause__),
                "suppress_context": error.__suppress_context__}
    return visit(error)

def fixture(context, interrupt):
    events = []
    primary = ValueError("selected child error")
    outer = primary if context == "same_primary" else RuntimeError("original outer handler")
    inner = LookupError("original inner handler")
    replacement = KeyboardInterrupt("foreign repr interrupted")
    leaf = object()
    class Key(str):
        def __repr__(self):
            current = sys.exception()
            events.append({"operation": "key.__repr__", "handled_is_none": current is None,
                "handled_is_outer": current is outer, "handled_is_inner": current is inner,
                "handled_is_primary": current is primary})
            if interrupt: raise replacement
            return "<same-key>"
    key = Key("key")
    container = {key: leaf}
    def default(value):
        assert value is leaf
        current = sys.exception()
        events.append({"operation": "selected_child", "handled_is_none": current is None,
            "handled_is_outer": current is outer, "handled_is_inner": current is inner,
            "handled_is_primary": current is primary})
        raise primary
    return {"events": events, "primary": primary, "outer": outer, "inner": inner,
            "replacement": replacement, "container": container, "key": key,
            "leaf": leaf, "default": default}

def original(values, module):
    try:
        json.dumps(values["container"], sort_keys=True, separators=(",", ":"),
                   ensure_ascii=False, allow_nan=False, default=values["default"])
    except BaseException:
        return sys.exception()
    raise AssertionError("original did not raise")

def capture_child(values):
    try: values["default"](values["leaf"])
    except BaseException: return sys.exception()
    raise AssertionError("selected child unexpectedly returned")

def fixed(values, module):
    error = capture_child(values)
    # This call is after the child handler has exited, as in a later native-issued
    # continuation. The caller's original outer handled exception is still live.
    return module.note(error, 1, values["container"], values["key"], 0)

def wrong_inside_child_handler(values, module):
    try: values["default"](values["leaf"])
    except BaseException:
        return module.note(sys.exception(), 1, values["container"], values["key"], 0)
    raise AssertionError("selected child unexpectedly returned")

def run(function, context, interrupt, module):
    values = fixture(context, interrupt)
    if context == "none":
        result = function(values, module)
    else:
        try: raise values["outer"]
        except BaseException:
            if context == "nested":
                try: raise values["inner"]
                except BaseException: result = function(values, module)
            else: result = function(values, module)
    return {"exception": state(result), "identity": {
        "primary": result is values["primary"], "replacement": result is values["replacement"]},
        "events": values["events"]}

CASE.mkdir(mode=0o700, exist_ok=False)
start = time.monotonic_ns()
before = {str(path): hashlib.sha256(path.read_bytes()).hexdigest()
          for path in (IMAGE, SOURCE, Path(__file__))}
report = {"schema": "hia.normalization.cpython314-note-context.development.v1",
          "scope": "Fixed note mechanism only. Full HIA coordinator path and physical recursion remain unqualified.",
          "python": sys.version, "before": before, "observations": [], "failures": []}
try:
    assert sys.version_info[:3] == (3, 14, 4)
    assert before[str(IMAGE)] == IMAGE_SHA and before[str(SOURCE)] == SOURCE_SHA
    spec = importlib.util.spec_from_file_location("_hia_normalization_note_314", IMAGE)
    module = importlib.util.module_from_spec(spec); spec.loader.exec_module(module)
    for context, interrupt in (("none", False), ("outer", False), ("nested", False),
            ("outer", True), ("nested", True), ("same_primary", False), ("same_primary", True)):
        expected = run(original, context, interrupt, module)
        actual = run(fixed, context, interrupt, module)
        row = {"context": context, "repr_interrupt": interrupt,
               "original": expected, "fixed": actual, "equal": expected == actual}
        report["observations"].append(row)
        assert row["equal"], row
    expected = run(original, "outer", False, module)
    wrong = run(wrong_inside_child_handler, "outer", False, module)
    assert expected != wrong, "negative control did not detect wrong handled-exception placement"
    expected_note = expected["events"][-1]
    wrong_note = wrong["events"][-1]
    assert expected_note["handled_is_outer"] and not expected_note["handled_is_primary"]
    assert wrong_note["handled_is_primary"] and not wrong_note["handled_is_outer"]
    report["observations"].append({"negative_control": "note_inside_child_except_is_observably_wrong",
                                   "original": expected, "wrong": wrong, "detected": True})
except BaseException:
    report["failures"].append(traceback.format_exc())
after = {str(path): hashlib.sha256(path.read_bytes()).hexdigest()
         for path in (IMAGE, SOURCE, Path(__file__))}
report.update(after=after, source_and_image_unchanged=before == after,
              elapsed_ns=time.monotonic_ns()-start,
              full_normalization_qualified=False, physical_recursion_qualified=False)
report["status"] = "PASS_FIXED_MECHANISM_ONLY" if not report["failures"] and before == after else "FAIL"
raw = (json.dumps(report, indent=2, sort_keys=True) + "\n").encode()
with (CASE/"RESULT.json").open("xb") as stream:
    stream.write(raw); stream.flush(); os.fsync(stream.fileno())
print(json.dumps({"status": report["status"], "observations": len(report["observations"]),
    "result": str(CASE/"RESULT.json"), "bytes": len(raw),
    "sha256": hashlib.sha256(raw).hexdigest()}, sort_keys=True))
if report["status"] == "FAIL": raise SystemExit(1)

