def _decode(value):
    if isinstance(value, VerifiedProgram):
        value = value.canonical_bytes
    try:
        caller_owned = type(value) in (dict, list)
        submitted_text = None
        if type(value) is bytes:
            if len(value) > MAX_BYTES:
                _reject("program exceeds byte budget", "E_HIA_LIMIT")
            value = value.decode("utf-8")
        if type(value) is str:
            _bounded_input_utf8_bytes(value)
            submitted_text = value
            # Bound value allocation before either selected decoder builds a
            # graph. An optional HIA value arena does not bypass the canonical
            # v7/composite Core verifier or rewrite its semantic checks.
            try:
                value = decode_hia_json(value, max_nodes=MAX_NODES, max_depth=MAX_DEPTH,
                                        object_pairs_hook=_unique_pairs, parse_constant=_bad_constant)
            except OverflowError as exc:
                raise HIAProgramRejected(
                    "program exceeds structural budget before JSON allocation",
                    "E_HIA_LIMIT") from exc
        if caller_owned:
            value = _bounded_detached_snapshot(value)
        _structure(value)
        raw = (selected_canonical_wire(submitted_text, max_nodes=MAX_NODES, max_depth=MAX_DEPTH)
               if submitted_text is not None else None)
        if raw is None:
            raw = json.dumps(value, sort_keys=True, separators=(",", ":"),
                             ensure_ascii=False, allow_nan=False).encode("utf-8")
        if len(raw) > MAX_BYTES:
            _reject("program exceeds byte budget", "E_HIA_LIMIT")
        # Validation uses a detached snapshot, never the caller's mutable dict.
        # This is our own already-structured, byte-bounded canonical output,
        # not a submitted wire. Preserve the existing detached-object bridge
        # without redundantly preflighting the same checked graph a second time.
        return decode_internal_canonical(raw, max_nodes=MAX_NODES, max_depth=MAX_DEPTH), raw
    except HIAProgramRejected:
        raise
    except (ValueError, TypeError, UnicodeError, RecursionError, OverflowError) as exc:
        raise HIAProgramRejected("invalid/deep UTF-8 JSON", "E_HIA_FORMAT") from exc

_structure.text:
def _structure(value):
    """Count exact canonical JSON bytes AND nodes before json.dumps.

    In-process dicts are not byte-bounded by the text preflight. The active
    identity set also refuses cycles, and queued leaf counts refuse huge
    container fanout before extending the work stack. This is a size gate,
    not a replacement for the canonical HIA typed SSA/ownership verifier.
    """
    # Repeated immutable keys/strings need the same arithmetic, not a second
    # character scan. This bounded table belongs to this one full traversal;
    # every occurrence still consumes its own nodes/bytes. A smaller remaining
    # budget always goes through the original helper, preserving its exact
    # lower-bound/escape/surrogate rejection order. No admission is memoized.
    string_sizes = {}

    def string_bytes(value, remaining):
        # Do not hash a caller's oversized string just to look it up. Preserve
        # the original constant-time lower-bound refusal before any full scan.
        if len(value) + 2 > remaining:
            return _json_string_bytes(value, remaining)
        size = string_sizes.get(value)
        if size is not None and size <= remaining:
            return size
        size = _json_string_bytes(value, remaining)
        if len(string_sizes) < 1024:
            string_sizes[value] = size
        return size

    # Keep node references directly, rather than allocating a task tuple for
    # every scalar. A private marker closes each active container and restores
    # its depth; it cannot be confused with any caller-provided JSON value.
    leaving = object()
    pending = [value]
    active = set()
    count, queued, size, depth = 0, 1, 0, 0
    while pending:
        current = pending.pop()
        if current is leaving:
            depth = pending.pop()
            active.remove(id(pending.pop()))
            continue
        queued -= 1
        count += 1
        if count > MAX_NODES or depth > MAX_DEPTH:
            _reject("program exceeds structural budget", "E_HIA_LIMIT")
        kind = type(current)
        if kind in (dict, list):
            identity = id(current)
            if identity in active:
                _reject("cyclic HIA JSON structure", "E_HIA_FORMAT")
            active.add(identity)
            children = len(current)
            if children > MAX_NODES - count - queued:
                _reject("program exceeds queued-node budget", "E_HIA_LIMIT")
            queued += children
            size += 2 + max(0, children - 1)  # container plus commas
            if kind is dict:
                size += children  # colons
                for key in current:
                    if type(key) is not str:
                        _reject("non-string JSON key", "E_HIA_FORMAT")
                    size += string_bytes(key, MAX_BYTES - size)
                values = current.values()
            else:
                values = current
            # Retain the original container until its active-path scope ends.
            # Children are still captured before descent, in the same order;
            # the stack therefore visits them right to left as before.
            pending.extend((current, depth, leaving))
            pending.extend(values)
            depth += 1
        elif kind is str:
            size += string_bytes(current, MAX_BYTES - size)
        elif kind is bool:
            size += 4 if current else 5
        elif kind is int:
            # Fail without converting a potentially enormous host integer
            # into a decimal string merely to discover it exceeds 8 MiB.
            if current.bit_length() > MAX_BYTES * 4:
                _reject("integer exceeds JSON byte budget", "E_HIA_LIMIT")
            size += len(str(current))
        elif current is None:
            size += 4
        else:
            _reject("only bounded integer JSON values are supported", "E_HIA_FORMAT")
        if size > MAX_BYTES:
            _reject("program exceeds byte budget before encoding", "E_HIA_LIMIT")
    return size

_bounded_detached_snapshot.text:
def _bounded_detached_snapshot(root):
    """Capture caller-owned JSON containers before byte accounting/encoding.

    `_structure(original)` followed by `json.dumps(original)` is a check/use
    race if another thread mutates the original dict or list. Instead retain
    bounded references to each container's children, build a separate plain
    dict/list tree, and validate/serialize *that exact detached tree*.
    A nested caller tree is not claimed to be atomically snapshotted.
    Every supported capture is independently rechecked by _structure.
    """
    # Frames contain only active containers. Their iterators traverse the
    # bounded, already captured child references, never the live caller tree.
    # No per-leaf (node, parent, slot, depth, leaving) tasks or reversed
    # enumerate lists are needed. Retaining each original container also
    # prevents its identity being recycled while it remains on the active path.
    frames = []
    active = set()
    count, queued = 0, 1
    result = None
    node, parent, slot = root, None, None
    while True:
        queued -= 1
        count += 1
        if count > MAX_NODES or len(frames) > MAX_DEPTH:
            _reject("caller-owned tree exceeds snapshot budget", "E_HIA_LIMIT")
        kind = type(node)
        if kind in (dict, list):
            identity = id(node)
            if identity in active:
                _reject("cyclic caller-owned HIA tree", "E_HIA_FORMAT")
            active.add(identity)
            available = MAX_NODES - count - queued
            if len(node) > available:
                _reject("caller-owned tree exceeds queued-node budget", "E_HIA_LIMIT")
            children = []
            try:
                if kind is dict:
                    for key, child in node.items():
                        if type(key) is not str:
                            _reject("non-string caller-owned JSON key", "E_HIA_FORMAT")
                        if len(children) >= available:
                            _reject("caller-owned dictionary grew past node budget",
                                    "E_HIA_LIMIT")
                        children.append((key, child))
                    copy = {}
                else:
                    for child in node:
                        if len(children) >= available:
                            _reject("caller-owned list grew past node budget",
                                    "E_HIA_LIMIT")
                        children.append(child)
                    copy = [None] * len(children)
            except RuntimeError as exc:
                raise HIAProgramRejected(
                    "caller-owned tree mutated during bounded snapshot",
                    "E_HIA_FORMAT") from exc
            if parent is None:
                result = copy
            else:
                parent[slot] = copy
            queued += len(children)
            frames.append((node, iter(children) if kind is dict else enumerate(children), copy))
        else:
            if kind not in (str, int, bool) and node is not None:
                _reject("unsupported caller-owned JSON node", "E_HIA_FORMAT")
            if parent is None:
                result = node
            else:
                parent[slot] = node
        while frames:
            original, children, parent = frames[-1]
            try:
                slot, node = next(children)
                break
            except StopIteration:
                active.remove(id(original))
                frames.pop()
        else:
            return result

_bounded_input_utf8_bytes.text:
def _bounded_input_utf8_bytes(text):
    """Count encoded JSON-input bytes without materializing the entire wire.

    HIA accepts at most MAX_BYTES of UTF-8 input.  Encoding a large caller
    string just to check its size creates an unbounded pre-admission copy.
    Exact built-in str values are immutable; count them in bounded chunks.
    Each encoded temporary is at most 16 KiB (4096 Unicode code points).
    """
    if len(text) > MAX_BYTES:
        _reject("program exceeds byte budget", "E_HIA_LIMIT")
    if text.isascii():
        return len(text)
    total = 0
    for offset in range(0, len(text), 4096):
        total += len(text[offset:offset + 4096].encode("utf-8"))
        if total > MAX_BYTES:
            _reject("program exceeds byte budget", "E_HIA_LIMIT")
    return total

_json_string_bytes.text:
def _json_string_bytes(value, remaining):
    """Exact UTF-8 length of ensure_ascii=False compact JSON string output.

    No escaped/encoded string is materialized during this preflight. In
    particular a short sequence of control characters may require six
    serialized bytes for every source character.
    """
    if len(value) + 2 > remaining:
        _reject("program exceeds byte budget before encoding", "E_HIA_LIMIT")
    # The common identifier/opcode/key case needs no per-code-point Python loop.
    # The lower-bound budget check above remains first; no encoded copy or
    # verified-object cache is introduced, and every unsafe/non-ASCII string
    # still follows the complete original escape/surrogate/UTF-8 accounting.
    if value.isascii() and _JSON_ESCAPE.search(value) is None:
        return len(value) + 2
    size = 2  # opening and closing JSON quotes
    for char in value:
        point = ord(char)
        if point < 32:
            width = 2 if point in (8, 9, 10, 12, 13) else 6
        elif point in (34, 92):  # escaped double quote/backslash
            width = 2
        elif point < 0x80:
            width = 1
        elif 0xD800 <= point <= 0xDFFF:
            _reject("unpaired Unicode surrogate", "E_HIA_FORMAT")
        elif point < 0x800:
            width = 2
        elif point < 0x10000:
            width = 3
        else:
            width = 4
        size += width
        if size > remaining:
            _reject("program exceeds byte budget before encoding", "E_HIA_LIMIT")
    return size
